/**
 * railway.js — the Illinois Central's tracks along the lake east of Prairie Avenue,
 * 1904 (T-2478).
 *
 * WHAT IT DRAWS, from `data/railway/<scene>.json` (generated by
 * tools/trace_ic_tracks_1904.py from the Sanborn 1911 sheets 20 and 28 and the
 * authored spec data/railway/1904_spec.json):
 *
 *   the cinder ground   the right-of-way between its verges, trodden cinders
 *   the ballast beds    a darker, rougher bed 1.75 m either side of every track
 *   the ties            hewn crossties every 0.53 m, standing a few centimetres
 *                       proud of the cinders the photographs show filled up round them
 *   the rails           an 85-lb tee section at standard gauge
 *   the verges          weeds along both edges of the right-of-way, and a few
 *                       between the tracks, as crossed alpha cards
 *
 * Every number comes from the data file, which carries the spec's tiers and notes;
 * the maps come from `textures/prairie_1904_rail/` under the asset base. The
 * pictures are evidence of nothing (docs/LIBERTIES.md L-ic-tracks-2478).
 *
 * THE GROUND DRAWS LIKE A DECAL AND MUST NOT WRITE DEPTH. The cinders, the verges
 * and the beds lie two centimetres over the heightfield, in the transparent list
 * with `depthWrite: false` and a negative render order, as working-bank.js and
 * frontage.js do: an opaque decal with a slope-scaled polygon offset hides
 * anything low standing on it at distance, and the ties stand 2.5 cm proud.
 *
 * WHAT IT COSTS. Ten kilometres of track is twenty thousand ties and twenty
 * kilometres of rail. The yard is cut into zones along its length; a zone near the
 * eye draws its ties as boxes and its rails in full section, a far one draws each
 * tie as its top face and each rail as a three-face strip, and past the tie reach a
 * zone draws only the ground. Each zone is one draw for its rails and one for its
 * ties whichever level it is at, so the layer adds a dozen or so draws at most.
 *
 * A scene that does not list `railway` hands this no data base and it draws
 * nothing (T-1739). A failed fetch draws nothing and records a problem; maps that
 * do not arrive leave flat tones and a problem.
 */

import * as THREE from 'three';

const LIBRARY = 'textures/prairie_1904_rail/';
const MAPS = {
  cinder_ballast: 'ballast/cinder_ballast',
  trodden_cinders: 'ground/trodden_cinders',
  weedy_verge: 'verge/weedy_verge',
  tie_timber: 'timber/tie_timber',
};
const TUFT = 'foliage/grass_tuft';
const LEVEL = { attested: 0, inferred: 0.5, reconstructed: 1 };
/** Longest triangle edge after draping: the heightfield's own cell. */
const MAX_EDGE_M = 2.5;
/** Each ground surface's lift over the heightfield and its draw order. */
const GROUND = {
  cinders: { lift: 0.02, order: -3, fade: 1.2, colour: 0x4a4744 },
  verge: { lift: 0.022, order: -2, fade: 0.7, colour: 0x5f6a3c },
  bed: { lift: 0.024, order: -1, fade: 0.45, colour: 0x2e2d2c },
};
/** The zone length along the yard, metres of northing. */
const ZONE_M = 110;
/** Per level: full section within `near`, ties at all within `ties`, tufts within `tufts`. */
const REACH = {
  full: { near: 130, ties: 650, tufts: 240 },
  balanced: { near: 100, ties: 480, tufts: 170 },
  light: { near: 60, ties: 220, tufts: 100 },
};
const STEEL = new THREE.Color(0xa3a4a6);
const RUST = new THREE.Color(0x4f3527);
const HEAD_SIDE = new THREE.Color(0x6b5546);

const wx = (e) => e;
const wz = (n) => -n;

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/** A small seeded generator, so a tie's skew and a tuft's place are the same every load. */
function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* -------------------------------------------------------------------------- */
/* a track as a function of its own length                                     */
/* -------------------------------------------------------------------------- */

/**
 * The centreline with its running length, and a grade: the heightfield sampled
 * every metre and averaged over BLEND_M either way, because a rail does not follow
 * every few-centimetre wobble of a 2.5 m grid, and the ties must sit on the same
 * line the rails do.
 */
function trackPath(line, terrain) {
  const pts = line.map(([e, n]) => ({ e, n }));
  const cum = [0];
  for (let i = 1; i < pts.length; i += 1) cum.push(cum[i - 1] + Math.hypot(pts[i].e - pts[i - 1].e, pts[i].n - pts[i - 1].n));
  const length = cum[cum.length - 1];
  const locate = (s) => {
    s = Math.max(0, Math.min(length, s));
    let lo = 0; let hi = cum.length - 1;
    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= s) lo = mid; else hi = mid; }
    const seg = Math.max(cum[hi] - cum[lo], 1e-9);
    const f = (s - cum[lo]) / seg;
    const a = pts[lo]; const b = pts[hi];
    const te = (b.e - a.e) / seg; const tn = (b.n - a.n) / seg;
    return { e: a.e + (b.e - a.e) * f, n: a.n + (b.n - a.n) * f, te, tn };
  };
  const STEP = 1; const BLEND_M = 4;
  const raw = [];
  for (let s = 0; s <= length + 1e-6; s += STEP) { const p = locate(s); raw.push(terrain.surfaceHeight(p.e, p.n)); }
  const k = Math.round(BLEND_M / STEP);
  const grade = raw.map((_, i) => {
    let sum = 0; let c = 0;
    for (let j = Math.max(0, i - k); j <= Math.min(raw.length - 1, i + k); j += 1) { sum += raw[j]; c += 1; }
    return sum / c;
  });
  const gradeAt = (s) => {
    const x = Math.max(0, Math.min(grade.length - 1, s / STEP));
    const i = Math.floor(x); const f = x - i;
    return grade[i] * (1 - f) + (grade[Math.min(grade.length - 1, i + 1)] ?? grade[i]) * f;
  };
  /** Smoothed tangent at s: the chord over ±2.5 m, so a 5 m vertex does not kink a rail. */
  const at = (s) => {
    const p = locate(s);
    const a = locate(s - 2.5); const b = locate(s + 2.5);
    const L = Math.hypot(b.e - a.e, b.n - a.n) || 1;
    return { e: p.e, n: p.n, te: (b.e - a.e) / L, tn: (b.n - a.n) / L, y: gradeAt(s) };
  };
  return { length, at };
}

/* -------------------------------------------------------------------------- */
/* draped ribbons                                                              */
/* -------------------------------------------------------------------------- */

/**
 * A ribbon given as stations across it ([e_a, n_a, e_b, n_b] each), draped on the
 * heightfield with no triangle edge longer than MAX_EDGE_M, its two long edges faded
 * to nothing over `fade` metres so the ground it lies on shows through at the seam.
 * UVs are world metres on the yard's own axes, so beds, cinders and verges share a
 * grain where they overlap.
 */
function ribbon(stations, { terrain, lift, fade, axis, span, level, out }) {
  const { pos, uv, col, conf } = out;
  for (let i = 0; i + 1 < stations.length; i += 1) {
    const [ae0, an0, be0, bn0] = stations[i];
    const [ae1, an1, be1, bn1] = stations[i + 1];
    const along = Math.max(Math.hypot(ae1 - ae0, an1 - an0), Math.hypot(be1 - be0, bn1 - bn0));
    const width = Math.max(Math.hypot(be0 - ae0, bn0 - an0), Math.hypot(be1 - ae1, bn1 - an1), 1e-3);
    const nu = Math.max(1, Math.ceil(along / MAX_EDGE_M));
    const f = Math.min(0.45, fade / width);
    const inner = Math.max(1, Math.ceil((width * (1 - 2 * f)) / MAX_EDGE_M));
    const vs = [0, f];
    for (let j = 1; j < inner; j += 1) vs.push(f + ((1 - 2 * f) * j) / inner);
    vs.push(1 - f, 1);
    const vertex = (u, v) => {
      const ea = ae0 + (ae1 - ae0) * u; const na = an0 + (an1 - an0) * u;
      const eb = be0 + (be1 - be0) * u; const nb = bn0 + (bn1 - bn0) * u;
      const e = ea + (eb - ea) * v; const n = na + (nb - na) * v;
      const alpha = v <= 0 || v >= 1 ? 0 : 1;
      return [e, n, alpha];
    };
    for (let a = 0; a < nu; a += 1) {
      for (let b = 0; b + 1 < vs.length; b += 1) {
        const q = [vertex(a / nu, vs[b]), vertex((a + 1) / nu, vs[b]), vertex((a + 1) / nu, vs[b + 1]), vertex(a / nu, vs[b + 1])];
        // counter-clockwise in plan, so the faces look up
        const cross = (q[1][0] - q[0][0]) * (q[3][1] - q[0][1]) - (q[1][1] - q[0][1]) * (q[3][0] - q[0][0]);
        const tris = cross >= 0 ? [[0, 1, 2], [0, 2, 3]] : [[0, 2, 1], [0, 3, 2]];
        for (const t of tris) {
          for (const k of t) {
            const [e, n, alpha] = q[k];
            pos.push(wx(e), terrain.surfaceHeight(e, n) + lift, wz(n));
            uv.push((e * axis[0] + n * axis[1]) / span, (-e * axis[1] + n * axis[0]) / span);
            col.push(1, 1, 1, alpha);
            conf.push(level);
          }
        }
      }
    }
  }
}

function groundMesh(name, out, kind, lib, confidence) {
  const g = GROUND[kind];
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(out.pos, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(out.uv, 2));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(out.col, 4));
  geo.setAttribute('_confidence', new THREE.Float32BufferAttribute(out.conf, 1));
  geo.computeVertexNormals();
  geo.computeBoundingSphere();
  const mat = new THREE.MeshStandardMaterial({
    color: lib ? 0xffffff : g.colour, roughness: 1, metalness: 0, vertexColors: true,
    transparent: true, depthWrite: false,
    // one unit of bias, no slope term: the slope term is what pulled a decal over
    // the low timber standing on it at distance (T-2098)
    polygonOffset: true, polygonOffsetFactor: 0, polygonOffsetUnits: -1,
  });
  if (lib) {
    mat.map = lib.map; mat.normalMap = lib.normalMap; mat.roughnessMap = lib.orm; mat.aoMap = lib.orm;
    mat.aoMapIntensity = 0.6; mat.normalScale = new THREE.Vector2(0.9, 0.9);
  }
  mat.name = name;
  confidence?.patch(mat);
  mat.customProgramCacheKey = () => `chicago4d-railway-ground-${lib ? 'mapped' : 'flat'}`;
  const mesh = new THREE.Mesh(geo, mat);
  mesh.name = name;
  mesh.renderOrder = g.order;
  mesh.castShadow = false;
  mesh.receiveShadow = true;
  return mesh;
}

/* -------------------------------------------------------------------------- */
/* rails                                                                       */
/* -------------------------------------------------------------------------- */

/** The rail's cross-section, lateral x and height y from its base, open at the bottom. */
function railProfile(r, full) {
  const b = r.base_m / 2; const bd = r.base_depth_m; const w = r.web_m / 2;
  const hw = r.head_width_m / 2; const H = r.height_m; const hd = r.head_depth_m;
  if (!full) return [[-b, 0, 'rust'], [-hw, H, 'top'], [hw, H, 'top'], [b, 0, 'rust']];
  return [
    [-b, 0, 'rust'], [-b, bd, 'rust'], [-w, bd + 0.014, 'rust'], [-w, H - hd - 0.006, 'rust'],
    [-hw, H - hd, 'side'], [-hw, H - 0.004, 'side'], [-hw + 0.004, H, 'top'], [hw - 0.004, H, 'top'],
    [hw, H - 0.004, 'side'], [hw, H - hd, 'side'], [w, H - hd - 0.006, 'rust'], [w, bd + 0.014, 'rust'],
    [b, bd, 'rust'], [b, 0, 'rust'],
  ];
}

/** Both rails of one track, from s0 to s1, into the arrays given. */
function laySection(path, s0, s1, prof, spec, out) {
  const half = spec.gauge_m / 2 + spec.rail.head_width_m / 2;
  const seat = spec.ties.exposed_m + GROUND.bed.lift;
  const steps = Math.max(1, Math.ceil((s1 - s0) / 5));
  const ring = [];
  for (let i = 0; i <= steps; i += 1) ring.push(path.at(s0 + ((s1 - s0) * i) / steps));
  for (const side of [-1, 1]) {
    for (let i = 0; i < steps; i += 1) {
      const A = ring[i]; const B = ring[i + 1];
      // across the track, to its right looking along it: (tn, -te) in plan
      const placed = (p, [x, y]) => {
        const ox = side * half + x;
        return [p.e + p.tn * ox, p.y + seat + y, p.n - p.te * ox];
      };
      for (let j = 0; j + 1 < prof.length; j += 1) {
        const a0 = placed(A, prof[j]); const a1 = placed(A, prof[j + 1]);
        const b0 = placed(B, prof[j]); const b1 = placed(B, prof[j + 1]);
        const tone = prof[j][2] === 'top' && prof[j + 1][2] === 'top' ? STEEL
          : (prof[j][2] === 'rust' || prof[j + 1][2] === 'rust' ? RUST : HEAD_SIDE);
        // the face's outward normal: (-dy, dx) in the profile's own plane, laid across
        // the track ((tn, -te) in plan; three's z is -n)
        const dx = prof[j + 1][0] - prof[j][0]; const dy = prof[j + 1][1] - prof[j][1];
        const L = Math.hypot(dx, dy) || 1;
        const lx = -dy / L; const ly = dx / L;
        const te = (A.te + B.te) / 2; const tn = (A.tn + B.tn) / 2;
        const nrm = [tn * lx, ly, te * lx];
        // wind each face so its front is the side its normal leaves by
        const w = (p) => [p[0], p[1], -p[2]];
        const [P, Q, R] = [w(a0), w(b0), w(b1)];
        const ux = Q[0] - P[0]; const uy = Q[1] - P[1]; const uz = Q[2] - P[2];
        const vx = R[0] - P[0]; const vy = R[1] - P[1]; const vz = R[2] - P[2];
        const gx = uy * vz - uz * vy; const gy = uz * vx - ux * vz; const gz = ux * vy - uy * vx;
        const order = gx * nrm[0] + gy * nrm[1] + gz * nrm[2] >= 0
          ? [a0, b0, b1, a0, b1, a1] : [a0, b1, b0, a0, a1, b1];
        for (const p of order) {
          out.pos.push(wx(p[0]), p[1], wz(p[2]));
          out.nrm.push(nrm[0], nrm[1], nrm[2]);
          out.col.push(tone.r, tone.g, tone.b);
        }
      }
    }
  }
}

function railMesh(name, out, level, confidence, castShadow) {
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(out.pos, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(out.nrm, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(out.col, 3));
  geo.setAttribute('_confidence', new THREE.Float32BufferAttribute(new Float32Array(out.pos.length / 3).fill(level), 1));
  geo.computeBoundingSphere();
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, metalness: 0.2, roughness: 0.62 });
  mat.name = name;
  confidence?.patch(mat);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.name = name;
  mesh.castShadow = castShadow;
  mesh.receiveShadow = true;
  return mesh;
}

/* -------------------------------------------------------------------------- */
/* the layer                                                                   */
/* -------------------------------------------------------------------------- */

async function loadMaps(assetBase) {
  const loader = new THREE.TextureLoader();
  const base = new URL(LIBRARY, assetBase);
  const tex = async (url, srgb) => {
    const t = await loader.loadAsync(url);
    t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.anisotropy = 8;
    return t;
  };
  const out = new Map();
  await Promise.all(Object.entries(MAPS).map(async ([id, dir]) => {
    const here = new URL(`${dir}/`, base);
    const sheet = await getJSON(new URL('material.json', here));
    const [map, normalMap, orm] = await Promise.all([
      tex(new URL(sheet.web.basecolor, here).href, true),
      tex(new URL(sheet.web.normal_gl, here).href, false),
      tex(new URL(sheet.web.orm, here).href, false),
    ]);
    out.set(id, { map, normalMap, orm, along: Number(sheet.span_along_m ?? sheet.span_m), across: sheet.span_across_m, sheet });
  }));
  const here = new URL(`${TUFT}/`, base);
  const sheet = await getJSON(new URL('material.json', here));
  const map = await loader.loadAsync(new URL(sheet.web.basecolor_alpha, here).href);
  map.colorSpace = THREE.SRGBColorSpace;
  out.set('grass_tuft', { map, sheet });
  return out;
}

/**
 * A tie as the eye sees it: its top and its two long faces, unit size with the origin
 * at the top. The bottom is buried and the ends are 2.5 cm of end grain, so neither is
 * drawn: six triangles where a box spends twelve.
 */
function tieGeometry() {
  const pos = []; const uv = []; const nrm = [];
  const quad = (p, n, uvs) => {
    for (const k of [0, 1, 2, 0, 2, 3]) { pos.push(...p[k]); nrm.push(...n); uv.push(...uvs[k]); }
  };
  const h = 0.5;
  // top, its x along the tie's length (the map's x) and z across it
  quad([[-h, 0, h], [h, 0, h], [h, 0, -h], [-h, 0, -h]], [0, 1, 0], [[0, 0], [1, 0], [1, 1], [0, 1]]);
  // the two long faces, facing along the track
  quad([[-h, -1, h], [h, -1, h], [h, 0, h], [-h, 0, h]], [0, 0, 1], [[0, 0], [1, 0], [1, 0.08], [0, 0.08]]);
  quad([[h, -1, -h], [-h, -1, -h], [-h, 0, -h], [h, 0, -h]], [0, 0, -1], [[1, 0.92], [0, 0.92], [0, 1], [1, 1]]);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  return geo;
}

/** The crossed card a tuft is drawn with: two upright quads, unit height, normals up. */
function tuftGeometry(aspect) {
  const w = aspect / 2;
  const pos = []; const uv = []; const nrm = [];
  for (const [dx, dz] of [[1, 0], [0, 1]]) {
    const q = [[-w * dx, 0, -w * dz, 0, 0], [w * dx, 0, w * dz, 1, 0], [w * dx, 1, w * dz, 1, 1], [-w * dx, 1, -w * dz, 0, 1]];
    for (const k of [0, 1, 2, 0, 2, 3]) { pos.push(q[k][0], q[k][1], q[k][2]); uv.push(q[k][3], q[k][4]); nrm.push(0, 1, 0); }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  geo.setAttribute('_confidence', new THREE.Float32BufferAttribute(new Float32Array(pos.length / 3).fill(1), 1));
  return geo;
}

/**
 * @param {object} o dataBase (data/ root, or null when the scene does not list the
 *                   layer) · assetBase · sceneId · terrain · confidence · problems ·
 *                   detail ('full' | 'balanced' | 'light')
 */
export async function createRailway({
  dataBase, assetBase = null, sceneId, terrain, confidence = null, problems = [], detail = 'full',
} = {}) {
  const group = new THREE.Group();
  group.name = 'railway';
  const out = {
    group,
    data: null,
    census: { tracks: 0, track_m: 0, ties: 0, tufts: 0, zones: 0, textured: false },
    update: () => {},
    setDetail: () => {},
    pickAt: () => null,
    dispose: () => {},
  };
  if (!dataBase || !terrain) return out;
  let data;
  try {
    data = await getJSON(new URL(`railway/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`railway: ${err.message} — no track is drawn`);
    return out;
  }
  out.data = data;
  let maps = new Map();
  if (assetBase) {
    try {
      maps = await loadMaps(assetBase);
      out.census.textured = true;
    } catch (err) {
      problems.push(`railway maps not bound — ${err.message}`);
      maps = new Map();
    }
  }

  const tracks = (data.tracks ?? []).filter((t) => (t.centreline_local_m ?? []).length >= 2);
  const paths = tracks.map((t) => trackPath(t.centreline_local_m, terrain));
  out.census.tracks = tracks.length;
  out.census.track_m = Math.round(paths.reduce((a, p) => a + p.length, 0));

  // The yard's own axis, from its longest track: the ground's grain runs along it.
  const longest = tracks[paths.indexOf(paths.reduce((a, p) => (p.length > a.length ? p : a), paths[0]))];
  const [f0, f1] = [longest.centreline_local_m[0], longest.centreline_local_m.at(-1)];
  const AL = Math.hypot(f1[0] - f0[0], f1[1] - f0[1]) || 1;
  const axis = [(f1[0] - f0[0]) / AL, (f1[1] - f0[1]) / AL];

  const spec = data;
  const tierLevel = (t) => LEVEL[t] ?? 1;
  const meshes = [];
  const materials = [];
  const geometries = [];

  /* ---- the ground: cinders, verges, beds ---- */
  const row = data.right_of_way ?? {};
  const buffers = () => ({ pos: [], uv: [], col: [], conf: [] });
  const cinders = buffers();
  const ground = maps.get(spec.ballast?.right_of_way_material ?? 'trodden_cinders');
  ribbon(row.cinders ?? [], {
    terrain, lift: GROUND.cinders.lift, fade: GROUND.cinders.fade, axis, span: ground?.along ?? 4,
    level: tierLevel(spec.ballast?.tier ?? 'inferred'), out: cinders,
  });
  const verge = buffers();
  const vergeLib = maps.get(spec.verges?.material ?? 'weedy_verge');
  for (const v of row.verges ?? []) {
    ribbon(v.stations ?? [], {
      terrain, lift: GROUND.verge.lift, fade: GROUND.verge.fade, axis, span: vergeLib?.along ?? 3,
      level: tierLevel(spec.verges?.tier ?? 'reconstructed'), out: verge,
    });
  }
  const bed = buffers();
  const bedLib = maps.get(spec.ballast?.material ?? 'cinder_ballast');
  const halfBed = spec.ballast?.bed_half_width_m ?? 1.75;
  tracks.forEach((t, i) => {
    const p = paths[i];
    const st = [];
    for (let s = 0; s <= p.length + 1e-6; s += 5) {
      const a = p.at(Math.min(s, p.length));
      st.push([a.e - a.tn * halfBed, a.n + a.te * halfBed, a.e + a.tn * halfBed, a.n - a.te * halfBed]);
    }
    if (p.length % 5 > 0.5) {
      const a = p.at(p.length);
      st.push([a.e - a.tn * halfBed, a.n + a.te * halfBed, a.e + a.tn * halfBed, a.n - a.te * halfBed]);
    }
    ribbon(st, {
      terrain, lift: GROUND.bed.lift, fade: GROUND.bed.fade, axis, span: bedLib?.along ?? 2,
      level: Math.max(tierLevel(spec.ballast?.tier ?? 'inferred'), tierLevel(t.geometry_tier)), out: bed,
    });
  });
  const groundMeshes = [
    groundMesh('railway-cinders', cinders, 'cinders', ground, confidence),
    groundMesh('railway-verges', verge, 'verge', vergeLib, confidence),
    groundMesh('railway-ballast-beds', bed, 'bed', bedLib, confidence),
  ];
  for (const m of groundMeshes) { group.add(m); meshes.push(m); materials.push(m.material); geometries.push(m.geometry); }

  /* ---- zones along the yard: rails, ties and tufts ---- */
  const ns = tracks.flatMap((t) => t.centreline_local_m.map(([, n]) => n));
  const nTop = Math.max(...ns); const nBot = Math.min(...ns);
  const zoneCount = Math.max(1, Math.ceil((nTop - nBot) / ZONE_M));
  const zones = Array.from({ length: zoneCount }, (_, z) => ({
    nHi: nTop - z * ZONE_M, nLo: nTop - (z + 1) * ZONE_M,
    railNear: { pos: [], nrm: [], col: [] }, railFar: { pos: [], nrm: [], col: [] },
    ties: [], tufts: [], eSum: 0, eCount: 0,
  }));
  const zoneOf = (n) => zones[Math.max(0, Math.min(zoneCount - 1, Math.floor((nTop - n) / ZONE_M)))];

  const profNear = railProfile(spec.rail, true);
  const profFar = railProfile(spec.rail, false);
  const ties = spec.ties;
  const tieRand = rng(19040701);
  const trackLevel = tracks.map((t) => Math.max(tierLevel(t.geometry_tier), tierLevel(spec.rail?.tier ?? 'reconstructed')));
  tracks.forEach((t, i) => {
    const p = paths[i];
    // rails, cut where the track crosses from one zone into the next
    let s0 = 0; let z0 = zoneOf(p.at(0).n);
    const CUT = 2.5;
    for (let s = CUT; s <= p.length + CUT - 1e-6; s += CUT) {
      const sc = Math.min(s, p.length);
      const z = zoneOf(p.at(sc).n);
      if (z !== z0 || sc >= p.length) {
        laySection(p, s0, sc, profNear, spec, z0.railNear);
        laySection(p, s0, sc, profFar, spec, z0.railFar);
        z0.level = Math.max(z0.level ?? 0, trackLevel[i]);
        s0 = sc; z0 = z;
      }
    }
    // ties: every spacing, nudged, skewed and cut a little long or short as a
    // hand-laid track is
    for (let s = ties.spacing_m / 2; s < p.length; s += ties.spacing_m) {
      const sj = s + (tieRand() - 0.5) * 2 * ties.jitter.along_m;
      const a = p.at(Math.max(0, Math.min(p.length, sj)));
      const yaw = Math.atan2(a.tn, a.te) + ((tieRand() - 0.5) * 2 * ties.jitter.skew_deg * Math.PI) / 180;
      const length = ties.length_m + (tieRand() - 0.5) * 2 * ties.jitter.length_m;
      const shift = (tieRand() - 0.5) * 0.08;
      const tone = 0.78 + tieRand() * 0.34;
      const z = zoneOf(a.n);
      z.ties.push({ e: a.e + a.tn * shift, n: a.n - a.te * shift, y: a.y + GROUND.bed.lift + ties.exposed_m, yaw, length, tone, warm: tieRand() });
      z.eSum += a.e; z.eCount += 1;
    }
  });

  /* ---- tufts: the verges at their density, and a few between the tracks ---- */
  const tuftLib = maps.get('grass_tuft');
  const dens = spec.verges?.tufts_per_m2 ?? { full: 3.2, balanced: 1.8, light: 0.8 };
  const between = spec.verges?.between_tracks_per_m2 ?? { full: 0.12, balanced: 0.06, light: 0 };
  const tuftRand = rng(19040702);
  const nearTrack = (e, n, clear) => {
    for (const t of tracks) {
      const line = t.centreline_local_m;
      for (let i = 0; i + 1 < line.length; i += 1) {
        const [e0, n0] = line[i]; const [e1, n1] = line[i + 1];
        if ((n > Math.max(n0, n1) + clear) || (n < Math.min(n0, n1) - clear)) continue;
        const dx = e1 - e0; const dn = n1 - n0; const L2 = dx * dx + dn * dn || 1;
        const f = Math.max(0, Math.min(1, ((e - e0) * dx + (n - n0) * dn) / L2));
        if (Math.hypot(e - (e0 + dx * f), n - (n0 + dn * f)) < clear) return true;
      }
    }
    return false;
  };
  const scatter = (stations, density, ratioOf, clear = 0) => {
    for (let i = 0; i + 1 < stations.length; i += 1) {
      const [ae0, an0, be0, bn0] = stations[i];
      const [ae1, an1, be1, bn1] = stations[i + 1];
      const area = 0.5 * Math.abs((be0 - ae1) * (bn1 - an0) - (be1 - ae0) * (bn0 - an1));
      const want = area * density;
      let count = Math.floor(want) + (tuftRand() < want % 1 ? 1 : 0);
      while (count-- > 0) {
        const u = tuftRand(); let v = tuftRand();
        // clustered: a tuft likes company, and the verge is thickest at its outer edge
        v = clear ? v : v ** 0.8;
        const e = (ae0 + (ae1 - ae0) * u) * (1 - v) + (be0 + (be1 - be0) * u) * v;
        const n = (an0 + (an1 - an0) * u) * (1 - v) + (bn0 + (bn1 - bn0) * u) * v;
        if (clear && nearTrack(e, n, clear)) continue;
        zoneOf(n).tufts.push({
          e, n, y: terrain.surfaceHeight(e, n) + GROUND.verge.lift - 0.02,
          yaw: tuftRand() * Math.PI, scale: 0.55 + tuftRand() * 0.75, keep: tuftRand() / ratioOf,
          tone: 0.8 + tuftRand() * 0.35,
        });
      }
    }
  };
  if (tuftLib) {
    for (const v of row.verges ?? []) scatter(v.stations ?? [], dens.full, 1);
    if (between.full > 0) scatter(row.cinders ?? [], between.full, 1, (spec.ballast?.bed_half_width_m ?? 1.75) + 0.2);
  }

  /* ---- build each zone's meshes ---- */
  const tieGeoNear = tieGeometry();
  const tieGeoFar = new THREE.PlaneGeometry(1, 1);
  tieGeoFar.rotateX(-Math.PI / 2);
  for (const g of [tieGeoNear, tieGeoFar]) {
    g.setAttribute('_confidence', new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count).fill(tierLevel(ties.tier)), 1));
    geometries.push(g);
  }
  const timber = maps.get('tie_timber');
  const tieMat = new THREE.MeshStandardMaterial({ color: timber ? 0xffffff : 0x6e655a, roughness: 0.9, metalness: 0 });
  if (timber) {
    tieMat.map = timber.map; tieMat.normalMap = timber.normalMap; tieMat.roughnessMap = timber.orm;
    tieMat.normalScale = new THREE.Vector2(0.8, 0.8);
  }
  tieMat.name = 'railway-ties';
  confidence?.patch(tieMat);
  materials.push(tieMat);
  let tuftGeo = null; let tuftMat = null;
  if (tuftLib) {
    tuftGeo = tuftGeometry(tuftLib.sheet.width_m / tuftLib.sheet.height_m);
    geometries.push(tuftGeo);
    tuftMat = new THREE.MeshStandardMaterial({
      map: tuftLib.map, alphaTest: 0.45, side: THREE.DoubleSide, roughness: 0.92, metalness: 0,
    });
    tuftMat.name = 'railway-tufts';
    // A card's normal points up on both faces: three flips a double-sided face's
    // normal when its back is seen, which drew every tuft with the sun behind it black.
    tuftMat.onBeforeCompile = (shader) => {
      shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_begin>',
        '#include <normal_fragment_begin>\nnormal = normalize( vNormal );\nnonPerturbedNormal = normal;');
    };
    confidence?.patch(tuftMat);
    materials.push(tuftMat);
  }
  const m4 = new THREE.Matrix4(); const q = new THREE.Quaternion(); const up = new THREE.Vector3(0, 1, 0);
  const v3 = new THREE.Vector3(); const s3 = new THREE.Vector3(); const c = new THREE.Color();
  const tieDepth = Math.min(ties.depth_m, 0.12);   // only the top of a tie is ever above the cinders
  for (const [zi, z] of zones.entries()) {
    z.centre = new THREE.Vector3(z.eCount ? z.eSum / z.eCount : (f0[0] + f1[0]) / 2, 0, wz((z.nHi + z.nLo) / 2));
    if (z.railNear.pos.length) {
      z.railsNear = railMesh(`railway-rails-z${zi}`, z.railNear, z.level ?? 1, confidence, true);
      z.railsFar = railMesh(`railway-rails-far-z${zi}`, z.railFar, z.level ?? 1, confidence, false);
      z.railsFar.material.dispose();
      z.railsFar.material = z.railsNear.material;
      for (const m of [z.railsNear, z.railsFar]) { group.add(m); meshes.push(m); geometries.push(m.geometry); }
      materials.push(z.railsNear.material);
    }
    z.railNear = null; z.railFar = null;
    if (z.ties.length) {
      const near = new THREE.InstancedMesh(tieGeoNear, tieMat, z.ties.length);
      const far = new THREE.InstancedMesh(tieGeoFar, tieMat, z.ties.length);
      z.ties.forEach((t, k) => {
        q.setFromAxisAngle(up, t.yaw + Math.PI / 2);
        m4.compose(v3.set(wx(t.e), t.y, wz(t.n)), q, s3.set(t.length, tieDepth, ties.width_m));
        near.setMatrixAt(k, m4);
        c.setRGB(t.tone, t.tone * (0.97 + 0.05 * t.warm), t.tone * (0.92 + 0.06 * t.warm));
        near.setColorAt(k, c);
      });
      far.instanceMatrix = near.instanceMatrix;
      far.instanceColor = near.instanceColor;
      near.computeBoundingSphere(); far.boundingSphere = near.boundingSphere;
      near.name = `railway-ties-z${zi}`; far.name = `railway-ties-far-z${zi}`;
      near.castShadow = false; far.castShadow = false; near.receiveShadow = true; far.receiveShadow = true;
      group.add(near, far);
      z.tiesNear = near; z.tiesFar = far;
      out.census.ties += z.ties.length;
    }
    z.ties = null;
    if (tuftGeo && z.tufts.length) {
      z.tufts.sort((a, b) => a.keep - b.keep);
      const mesh = new THREE.InstancedMesh(tuftGeo, tuftMat, z.tufts.length);
      z.tufts.forEach((t, k) => {
        q.setFromAxisAngle(up, t.yaw);
        const h = tuftLib.sheet.height_m * t.scale;
        m4.compose(v3.set(wx(t.e), t.y, wz(t.n)), q, s3.set(h, h, h));
        mesh.setMatrixAt(k, m4);
        mesh.setColorAt(k, c.setRGB(t.tone, t.tone, t.tone * 0.92));
      });
      mesh.computeBoundingSphere();
      mesh.name = `railway-tufts-z${zi}`;
      mesh.castShadow = false; mesh.receiveShadow = true;
      z.tuftKeeps = z.tufts.map((t) => t.keep);
      z.tuftMesh = mesh;
      group.add(mesh);
    }
    z.tufts = null;
  }
  out.census.zones = zoneCount;

  /* ---- level and reach ---- */
  let level = REACH[detail] ? detail : 'full';
  const applyDetail = () => {
    out.census.tufts = 0;
    const want = dens[level] ?? 0; const full = dens.full || 1;
    for (const z of zones) {
      if (!z.tuftMesh) continue;
      const ratio = want / full;
      let n = 0; while (n < z.tuftKeeps.length && z.tuftKeeps[n] < ratio) n += 1;
      z.tuftMesh.count = n;
      out.census.tufts += n;
    }
  };
  applyDetail();
  out.setDetail = (next) => { if (REACH[next]) { level = next; applyDetail(); } };

  /** Per frame: which zones draw in full, which far, which not at all. */
  out.update = (camera) => {
    if (!camera) return;
    const r = REACH[level];
    const cx = camera.position.x; const cz = camera.position.z; const cy = camera.position.y;
    for (const z of zones) {
      // distance from the eye to the zone's span of northing, and to its middle across
      const n = -cz;
      const dn = n > z.nHi ? n - z.nHi : (n < z.nLo ? z.nLo - n : 0);
      const de = Math.max(0, Math.abs(cx - z.centre.x) - 30);
      const d = Math.hypot(dn, de, Math.max(0, cy - 30));
      const near = d < r.near;
      if (z.railsNear) { z.railsNear.visible = near; z.railsFar.visible = !near; }
      if (z.tiesNear) { z.tiesNear.visible = near; z.tiesFar.visible = !near && d < r.ties; }
      if (z.tuftMesh) z.tuftMesh.visible = d < r.tufts && z.tuftMesh.count > 0;
    }
  };

  /* ---- what a pick answers ---- */
  const raycaster = new THREE.Raycaster();
  const nearestTrack = (e, n) => {
    let best = null; let bd = Infinity;
    tracks.forEach((t) => {
      const line = t.centreline_local_m;
      for (let i = 0; i + 1 < line.length; i += 1) {
        const [e0, n0] = line[i]; const [e1, n1] = line[i + 1];
        const dx = e1 - e0; const dn = n1 - n0; const L2 = dx * dx + dn * dn || 1;
        const f = Math.max(0, Math.min(1, ((e - e0) * dx + (n - n0) * dn) / L2));
        const d = Math.hypot(e - (e0 + dx * f), n - (n0 + dn * f));
        if (d < bd) { bd = d; best = t; }
      }
    });
    return { track: best, distance: bd };
  };
  out.cardFor = (e, n) => railwayCard(data, nearestTrack(e, n));
  out.pickAt = (ndc, camera) => {
    if (!camera) return null;
    raycaster.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    raycaster.far = Math.max(400, camera.position.y * 4);
    const hits = raycaster.intersectObjects(groundMeshes, false);
    if (!hits.length) return null;
    const hit = hits[0];
    const record = out.cardFor(hit.point.x, -hit.point.z);
    return { id: record.id, record, point: hit.point.clone(), distance: hit.distance };
  };

  out.dispose = () => {
    for (const g of geometries) g.dispose();
    for (const m of materials) m.dispose();
    for (const z of zones) { z.tiesNear?.dispose(); z.tiesFar?.dispose(); z.tuftMesh?.dispose(); }
    for (const lib of maps.values()) { lib.map?.dispose(); lib.normalMap?.dispose(); lib.orm?.dispose(); }
  };
  group.userData.census = out.census;
  return out;
}

/* -------------------------------------------------------------------------- */
/* the card                                                                    */
/* -------------------------------------------------------------------------- */

const SAID = {
  traced: 'drawn on the sheet',
  joined_across_gap: 'joined across the gap between sheets 20 and 28',
  carried_past_sheet: 'carried past the edge of the sheet that draws it',
  closes_on_neighbour: 'closed on the next track, as a ladder would',
};

function railwayCard(data, { track, distance }) {
  const onTrack = track && distance < 3.5;
  const how = onTrack
    ? [...new Set((track.segments ?? []).map((s) => SAID[s.how] ?? s.how))].join('; ')
    : '';
  const r = data.rail ?? {}; const t = data.ties ?? {}; const b = data.ballast ?? {}; const v = data.verges ?? {};
  const sources = data.sources ?? [];
  return {
    id: onTrack ? `railway.${track.id}` : 'railway.right_of_way',
    sidecar: {
      name: onTrack ? `Illinois Central — track ${Number(track.id.split('_').at(-1))}` : 'Illinois Central — the right-of-way',
      phase: null,
      change_note: onTrack
        ? `One of the ${data.tracks.length} tracks the 1911 Sanborn sheets draw beside the lake here, `
          + `${Math.round(track.length_m)} m of it in this scene: ${how}. `
          + `${Math.round(track.traced_fraction * 100)}% of it is read off the sheet; the rest is ours.`
        : 'The railway\'s ground between Prairie Avenue\'s lots and the lake: trodden locomotive cinders with '
          + 'the tracks laid in them and weeds along the edges. In 1904 the lake came right up to this embankment; '
          + 'the beach and the park east of here are the 1920s fill.',
      placement: {
        symbolic_location: 'East of Prairie and Calumet Avenues, 16th to 22nd Street',
        position_confidence: onTrack ? track.geometry_tier : 'reconstructed',
        position_sources: sources,
        position_note: onTrack
          ? 'Traced off the 1911 Sanborn sheets 20 and 28 (tools/trace_ic_tracks_1904.py); 1911 stands in for 1904.'
          : (data.right_of_way?.note ?? ''),
      },
      attributes: {
        gauge: { value: '4 ft 8½ in (1.435 m)', confidence: 'inferred', sources: [], note: data.gauge_note ?? '' },
        rail: { value: r.section ?? '', confidence: r.tier ?? 'reconstructed', sources: [], note: r.note ?? '' },
        ties: {
          value: `${t.length_m} m × ${t.width_m} m, every ${t.spacing_m} m`, confidence: t.tier ?? 'reconstructed',
          sources: t.sources ?? [], note: t.note ?? '',
        },
        ballast: {
          value: 'locomotive cinders, filled to the ties', confidence: b.tier ?? 'inferred',
          sources: b.sources ?? [], note: b.note ?? '',
        },
        verges: { value: 'grass and weeds', confidence: v.tier ?? 'reconstructed', sources: [], note: v.note ?? '' },
      },
      citations: [],
      research_doc: data.research ?? 'docs/RESEARCH/ic_lakefront_1904.md',
      research_note: `The 1904 lakefront railway (T-2478); the liberties it takes are ${data.liberty ?? 'L-ic-tracks-2478'}.`,
    },
  };
}
